import{_ as n,a as i,b as s}from"./chunks/gruppenprozesse-schuelerdatensaetze-loeschen-ja.BXJfdX2U.js";import{_ as l,o as t,c as a,a3 as h}from"./chunks/framework.z_KJ15Ep.js";const d="/bilder/schueler/tutorials-schueler-loeschen.png",r="/bilder/schueler/tutorials-schueler-loeschen-wiederherstellen-filter-aufheben.png",c="/bilder/schueler/tutorials-schueler-loeschen-wiederherstellen-papierkorb.png",o="/bilder/schueler/tutorials-schueler-loeschen-wiederherstellen-individuell.png",u="/bilder/schueler/tutorials-schueler-loeschen-wiederherstellen-ueber-gp.png",p="/bilder/schueler/tutorials-schueler-loeschen-wiederherstellen-ausfuehren.png",v=JSON.parse('{"title":"Schülerdatensätze löschen und wiederherstellen","description":"","frontmatter":{"title":"Schülerdatensätze löschen und wiederherstellen","source_pageid":1240,"source_revision":7219},"headers":[],"relativePath":"schild3/schueler/schueler-loeschen-und-wiederherstellen-tutorial.md","filePath":"schild3/schueler/schueler-loeschen-und-wiederherstellen-tutorial.md"}'),m={name:"schild3/schueler/schueler-loeschen-und-wiederherstellen-tutorial.md"};function g(S,e,b,w,f,k){return t(),a("div",null,[...e[0]||(e[0]=[h('<h1 id="schulerdatensatze-loschen-und-wiederherstellen" tabindex="-1">Schülerdatensätze löschen und wiederherstellen <a class="header-anchor" href="#schulerdatensatze-loschen-und-wiederherstellen" aria-label="Permalink to &quot;Schülerdatensätze löschen und wiederherstellen&quot;">​</a></h1><p>Unterscheiden Sie den Löschvermerk vom endgültigen Entfernen eines Schülerdatensatzes. Mit Löschvermerk versehene Datensätze können aus dem Papierkorb wiederhergestellt werden.</p><h2 id="schuler-loschen" tabindex="-1">Schüler löschen <a class="header-anchor" href="#schuler-loschen" aria-label="Permalink to &quot;Schüler löschen&quot;">​</a></h2><p><a href="/bilder/schueler/tutorials-schueler-loeschen.png"><img src="'+d+'" alt="Löschen Sie Schüler mit einem Klick auf das &quot;-&quot;. Dies setzt einen Löschvermerk auf diesen Schüler und zeigt ihn nicht mehr an." loading="lazy"></a></p><p><em>Löschen Sie Schüler mit einem Klick auf das &quot;<strong>-</strong>&quot;. Dies setzt einen Löschvermerk auf diesen Schüler und zeigt ihn nicht mehr an.</em></p><p>Schüler lassen sich in der <em>Schüler</em>-Übersicht mit dem &quot;<strong>-</strong>&quot; aus dem Container entfernen.</p><p>Damit sind diese aber noch nicht aus der Datenbank entfernt, sondern werden lediglich mit einem <em>Löschvermerk</em> versehen und durch diesen nicht mehr aufgeführt.</p><p>Stattdessen wird der Schüler nur noch unter <em>Auswahl</em> ➜ <strong>Papierkorb zeigen</strong> angezeigt.</p><h2 id="schuler-wirklich-loschen" tabindex="-1">Schüler wirklich löschen <a class="header-anchor" href="#schuler-wirklich-loschen" aria-label="Permalink to &quot;Schüler wirklich löschen&quot;">​</a></h2><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-schueler-loeschen-auswahl.png"><img src="'+n+'" alt="Wählen Sie die Schüler mit Löschvermerk aus." loading="lazy"></a></p><p><em>Wählen Sie die Schüler mit Löschvermerk aus.</em></p><p>Um eine tatsächliche Löschung aus der Datenbank vorzunehmen, sind erst alle Schüler mit Löschvermerk über <em>Auswahl</em> ➜ <strong>Papierkorb zeigen</strong> anzuwählen.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-schuelerdatensaetze-loeschenl.png"><img src="'+i+'" alt="Markieren Sie die zu löschenden Schüler oder löschen Sie den ganzen Papierkorb." loading="lazy"></a></p><p><em>Markieren Sie die zu löschenden Schüler oder löschen Sie den ganzen Papierkorb.</em></p><p>Wechseln Sie auf den Reiter <em>Gruppenprozesse</em>.</p><p>Hier wählen Sie die Schüler aus, die tatsächlich gelöscht werden sollen - oder wenden Sie den Gruppenprozess auf die komplette Gruppe an.</p><p>Klicken Sie dann auf <code>Schüler-Datensätze löschen</code>.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-schuelerdatensaetze-loeschen-ja.png"><img src="'+s+'" alt="Bestätigen Sie den Löschvorgang mit Ja." loading="lazy"></a></p><p><em>Bestätigen Sie den Löschvorgang mit <code>Ja</code>.</em></p><p>Bestätigen Sie den Löschvorgang mit <code>Ja</code>.</p><p>Die Löschaktion wird durchgeführt und die Schüler sind dauerhaft aus der Datenbank entfernt.</p><p><a href="/bilder/schueler/tutorials-schueler-loeschen-wiederherstellen-filter-aufheben.png"><img src="'+r+'" alt="Stellen Sie die Standardauswahl im Schülerfilter wieder her." loading="lazy"></a></p><p><em>Stellen Sie die Standardauswahl im Schülerfilter wieder her.</em></p><p>Der Schülercontainer filtert aber noch immer auf den Papierkorb.</p><p>Klicken Sie auf das rote Filtersymbol, um die Standardeinstellung des Filters im Schülercontainer wiederherzustellen.</p><h2 id="schuler-wiederherstellen" tabindex="-1">Schüler wiederherstellen <a class="header-anchor" href="#schuler-wiederherstellen" aria-label="Permalink to &quot;Schüler wiederherstellen&quot;">​</a></h2><p>Sind Schüler noch im Papierkorb und nicht tatsächlich aus der Datenbank gelöscht, können diese wiederhergestellt werden, so dass sie wieder in der normalen Ansicht verfügbar sind.</p><p>Hierzu muss die <em>Löschmarkierung</em> wieder entfernt werden. Diese ist in den <em>Individualdaten</em> gespeichert, wird in den Masken <em>Individualdaten I</em> oder <em>Individualdaten II</em> nicht angezeigt.</p><p><a href="/bilder/schueler/tutorials-schueler-loeschen-wiederherstellen-papierkorb.png"><img src="'+c+'" alt="Lassen Sie sich den Papierkorb anzeigen." loading="lazy"></a></p><p><em>Lassen Sie sich den Papierkorb anzeigen.</em></p><p>Gehen Sie hierzu über <em>Auswahl</em> ➜ <strong>Papierkorb zeigen</strong>.</p><p>Sie bekommen alle Einträge mit Löschmarkierungen angezeigt.</p><p><a href="/bilder/schueler/tutorials-schueler-loeschen-wiederherstellen-individuell.png"><img src="'+o+'" alt="Stellen Sie gelöschte Datensätze aus den Papierkorb wieder her." loading="lazy"></a></p><p><em>Stellen Sie gelöschte Datensätze aus den Papierkorb wieder her.</em></p><p>Mit einem <code>Rechten Mausklick</code> wird ein Kontextmenü geöffnet, in welchem Sie <code>Löschmarkierung aufheben</code> auswählen und damit den Datensatz wieder so anzeigen lassen, wie es die Attribute - zum Beispiel der <em>Status</em> - vorgeben.</p><h3 id="wiederherstellung-uber-einen-gruppenprozess" tabindex="-1">Wiederherstellung über einen Gruppenprozess <a class="header-anchor" href="#wiederherstellung-uber-einen-gruppenprozess" aria-label="Permalink to &quot;Wiederherstellung über einen Gruppenprozess&quot;">​</a></h3><p><a href="/bilder/schueler/tutorials-schueler-loeschen-wiederherstellen-ueber-gp.png"><img src="'+u+'" alt="Dsa Wiederherstellen eines Schüler aus dem Papierkorb geht über Gruppenprozesse ➜ Individualdaten ändern. Hier wird die Löschmarkierung auf Nein gesetzt." loading="lazy"></a></p><p><em>Dsa Wiederherstellen eines Schüler aus dem Papierkorb geht über Gruppenprozesse ➜ <strong>Individualdaten ändern</strong>. Hier wird die <strong>Löschmarkierung</strong> auf Nein gesetzt.</em></p><p>Löschmarkierungen können weiterhin einzeln oder für Gruppen per Gruppenprozess entfernt werden.</p><p>Gehen Sie wie beim <em>Löschen aus der Datenbank</em> oben in <em>Auswahl</em> ➜ <strong>Papierkorb zeigen</strong>.</p><p>Wählen Sie den oder die wiederherzustellenden Schüler aus.</p><p>Gehen Sie nun über <em>Gruppenprozesse</em> ➜ <strong>Individualdaten ändern</strong> und setzen Sie unter <em>Allgemeine Angaben</em> die <strong>Löschmarkierung</strong> auf <em>Nein</em>.</p><p><a href="/bilder/schueler/tutorials-schueler-loeschen-wiederherstellen-ausfuehren.png"><img src="'+p+'" alt="Klicken Sie dann auf Ausführen und bestätigen Sie anschließend mit Ja." loading="lazy"></a></p><p><em>Klicken Sie dann auf <code>Ausführen</code> und bestätigen Sie anschließend mit <code>Ja</code>.</em></p><p>Klicken Sie auf <code>Ausführen</code> und dann bestätigen Sie mit <code>Ja</code> oder brechen Sie noch mit <code>Nein</code> ab.</p><p>Der Schüler ist nun wiederhergestellt.</p><p><a href="/bilder/schueler/tutorials-schueler-loeschen-wiederherstellen-filter-aufheben.png"><img src="'+r+'" alt="Stellen Sie die Standardauswahl im Schülerfilter wieder her." loading="lazy"></a></p><p><em>Stellen Sie die Standardauswahl im Schülerfilter wieder her.</em></p><p>Der Schülercontainer filtert aber noch immer auf den Papierkorb.</p><p>Klicken Sie auf das rote Filtersymbol, um die Standardeinstellung des Filters im Schülercontainer wiederherzustellen.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Sch%C3%BCler_l%C3%B6schen_und_wiederherstellen_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7219.</p>',52)])])}const L=l(m,[["render",g]]);export{v as __pageData,L as default};
